// ── Baseline: Prepare Input ─────────────────────────────────────────────────
const CONFIG = { model: 'gpt-4o-mini', timezone: 'Asia/Bangkok', calendarId: 'primary' };
const BASELINE_PROMPT = "You are a scheduling assistant. Given a Telegram message and the current date/time, perform all of the following tasks:\n1. Determine if the message contains actionable scheduling intent. If no, output {\"is_scheduling\": false} and stop.\n2. If yes, classify the intent (\"create\", \"modify\", \"cancel\").\n3. Extract event_title, start_datetime (ISO 8601), end_datetime (ISO 8601 or null), location (or null), and participants (list). Infer a 60-minute duration if end_datetime is not specified.\n4. Produce a JSON request body conforming to the Google Calendar Events API v3 schema for the extracted entities.\nOutput a single JSON object containing: \"is_scheduling\", \"intent\", \"entities\", and \"api_command\". Do not include any text outside the JSON object.";

const msg = $input.first().json.message;
if (!msg || typeof msg.text !== 'string' || !msg.text.trim() || msg.text.startsWith('/')) return [];
const now = $now.setZone(CONFIG.timezone);
const nowIso = now.toFormat("yyyy-MM-dd'T'HH:mm:ss");
return [{
  json: {
    config: CONFIG,
    text: msg.text.trim(),
    request: {
      model: CONFIG.model,
      temperature: 0,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: BASELINE_PROMPT },
        { role: 'user', content: `Current date/time: ${nowIso} (${now.toFormat('cccc')}), timezone ${CONFIG.timezone}\nMessage: ${msg.text.trim()}` },
      ],
    },
  },
}];

// ── Baseline: Parse Output ──────────────────────────────────────────────────
const ctx = $('Prepare Input').first().json;
let out = {};
try { out = JSON.parse($input.first().json.choices[0].message.content); } catch (e) { out = { parse_error: true }; }
const ok = out.is_scheduling === true && out.intent === 'create' && out.api_command && typeof out.api_command === 'object';
return [{ json: { config: ctx.config, ...out, ok } }];
